with kept_keys as (select id, event_type from web_events except all select id, event_type from web_events where session_id in (3, 31, 36, 39)), verified as (select s.* from web_events s inner join kept_keys k on s.id = k.id and s.event_type = k.event_type) select page, case when duration_sec >= 462 then 'LARGE' else 'SMALL' end as duration_sec_tier, count(*) filter (where event_type = 'search') as search_rows, min(event_time) as started_at, count(distinct page) as distinct_pages from verified group by page, case when duration_sec >= 462 then 'LARGE' else 'SMALL' end
